SET local check_function_bodies = off;

CREATE TABLE "better_supabase"."invoice_deliveries" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "invoice_id"   uuid                     NOT NULL,
  "channel"      text                     NOT NULL,
  "format"       text                     NOT NULL,
  "external_ref" text                     NOT NULL,
  "filename"     text,
  "sent_by"      uuid,
  "sent_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "invoice_deliveries_channel_check" CHECK (((length(channel) >= 1) AND (length(channel) <= 100))),
  CONSTRAINT "invoice_deliveries_external_ref_check" CHECK (((length(external_ref) >= 1) AND (length(external_ref) <= 500))),
  CONSTRAINT "invoice_deliveries_filename_check" CHECK ((length(filename) <= 255)),
  CONSTRAINT "invoice_deliveries_format_check" CHECK (((length(format) >= 1) AND (length(format) <= 100))),
  CONSTRAINT "invoice_deliveries_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."invoice_deliveries"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION api.list_invoice_deliveries (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."list_invoice_deliveries"($1) $function$;

CREATE OR REPLACE FUNCTION api.record_invoice_delivery (
  invoice      uuid,
  channel      text,
  format       text,
  external_ref text,
  filename     text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."record_invoice_delivery"($1, $2, $3, $4, $5) $function$;

CREATE OR REPLACE FUNCTION better_supabase.data_lifecycle_tables()
  RETURNS TABLE (
    subject  text,
    name     text,
    tbl      text,
    col      text,
    purge    boolean,
    omit     text[],
    exported boolean
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select t.subject, t.name, t.tbl, t.col, t.purge,
    t.omit || array(
      select a.attname::text
      from pg_catalog.pg_attribute a
      where a.attrelid = to_regclass(t.tbl)
        and a.attnum > 0
        and not a.attisdropped
        and a.attname ~* 'token|secret|_hash|password|api_key|license_key'
        and a.attname <> t.col
        and not a.attname = any(t.omit)
      order by a.attnum
    ) as omit,
    t.exported
  from (
  select * from (values
    ('user', 'better_supabase.audit_events', '"better_supabase"."audit_events"', 'actor_id', false, array['old_record', 'new_record', 'impersonated_by', 'impersonation_reason', 'support_session_id']::text[], true),
