GRANT EXECUTE ON FUNCTION "api"."list_invoice_deliveries"(uuid) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "api"."record_invoice_delivery"(uuid, text, text, text, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "api"."record_invoice_delivery"(uuid, text, text, text, text) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "better_supabase"."list_invoice_deliveries"(uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "better_supabase"."list_invoice_deliveries"(uuid) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "better_supabase"."record_invoice_delivery"(uuid, text, text, text, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "better_supabase"."record_invoice_delivery"(uuid, text, text, text, text) TO "authenticated", "service_role";

GRANT SELECT ON TABLE "better_supabase"."invoice_deliveries" TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "better_supabase"."invoice_deliveries" TO "service_role";
